class Solution {
public:
    vector<int> minOperations(string boxes) {
        int n = boxes.size();
        vector<int> ans(n, 0);
        int count = 0, sum = 0;
        for (int i = 0; i < n; i++) {
            ans[i] += i * count - sum;
            if (boxes[i] == '1') {
                count++;
                sum += i;
            }
        }
        count = 0;
        sum = 0;
        for (int i = n - 1; i >= 0; i--) {
            ans[i] += sum - i * count;
            if (boxes[i] == '1') {
                count++;
                sum += i;
            }
        }
        return ans;
    }
};
